<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\{User,Role,Request as LeadRequest};use Illuminate\Support\Facades\Hash;
class RequestTest extends TestCase{use RefreshDatabase;private function user($role=null){$u=User::create(['name'=>'U','phone'=>'+201'.random_int(100000000,999999999),'password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);if($role)$u->roles()->attach(Role::firstOrCreate(['name'=>$role]));return $u;}protected function setUp():void{parent::setUp();$this->artisan('migrate');}
public function test_guest_can_create():void{$this->postJson('/api/v1/requests',['name'=>'Guest','phone'=>'+201000000000','message'=>'Help'])->assertCreated();}
public function test_user_can_create_and_view_own():void{$u=$this->user('REGISTERED_USER');$r=$this->actingAs($u,'api')->postJson('/api/v1/requests',['name'=>'U','phone'=>$u->phone,'message'=>'Help']);$id=$r->json('data.id');$this->actingAs($u,'api')->getJson('/api/v1/my/requests')->assertOk();$this->actingAs($u,'api')->getJson("/api/v1/my/requests/$id")->assertOk();}
public function test_phone_required():void{$this->postJson('/api/v1/requests',['name'=>'Guest','message'=>'Help'])->assertStatus(422)->assertJsonValidationErrors('phone');}
public function test_admin_status_and_assignment_history():void{$a=$this->user('ADMIN');$r=$this->postJson('/api/v1/requests',['name'=>'Guest','phone'=>'+201000000000','message'=>'Help'])->json('data.id');$target=$this->user('ADMIN');$this->actingAs($a,'api')->putJson("/api/v1/admin/requests/$r/status",['status'=>'IN_PROGRESS'])->assertOk();$this->actingAs($a,'api')->postJson("/api/v1/admin/requests/$r/assign",['admin_id'=>$target->id])->assertOk();$this->assertDatabaseHas('request_assignments',['request_id'=>$r,'admin_id'=>$target->id]);}
public function test_user_cannot_view_others():void{$a=$this->user('REGISTERED_USER');$b=$this->user('REGISTERED_USER');$id=$this->actingAs($a,'api')->postJson('/api/v1/requests',['name'=>'A','phone'=>$a->phone,'message'=>'x'])->json('data.id');$this->actingAs($b,'api')->getJson("/api/v1/my/requests/$id")->assertNotFound();}}
